import { Board } from './board.js';
import { getLegalMoves, isCheckmate, isStalemate } from './rules.js';

/**
 * Provides a basic AI opponent using random or simple heuristic move selection.
 */

const PIECE_VALUES = {
    'p': 10,
    'n': 30,
    'b': 30,
    'r': 50,
    'q': 90,
    'k': 900
};

/**
 * Evaluates the board state for the given color.
 */
function evaluateBoard(board, aiColor) {
    let score = 0;
    for (let r = 0; r < 8; r++) {
        for (let c = 0; c < 8; c++) {
            const piece = board.getPiece(r, c);
            if (!piece) continue;
            const val = PIECE_VALUES[piece.toLowerCase()] || 0;
            if (piece === piece.toUpperCase()) {
                // White piece
                if (aiColor === 'W') score += val;
                else score -= val;
            } else {
                // Black piece
                if (aiColor === 'B') score += val;
                else score -= val;
            }
        }
    }
    return score;
}

/**
 * Returns a legal move object for the AI player based on difficulty.
 * Difficulty: 'easy' (random), 'medium' (greedy capture / basic heuristic), 'hard' (mini-max depth 2).
 * @param {Board} board 
 * @param {string} difficulty 
 * @returns {Object|null} {fromRow, fromCol, toRow, toCol, promotion}
 */
export function getAIMove(board, difficulty = 'medium') {
    const aiColor = board.turn; // 'W' or 'B'

    // Collect all legal moves for AI
    const allMoves = [];
    for (let r = 0; r < 8; r++) {
        for (let c = 0; c < 8; c++) {
            const piece = board.getPiece(r, c);
            if (!piece) continue;
            const isWhitePiece = piece === piece.toUpperCase();
            const pieceColor = isWhitePiece ? 'W' : 'B';
            if (pieceColor === aiColor) {
                const legalDestinations = getLegalMoves(board, r, c);
                for (const dest of legalDestinations) {
                    allMoves.push({
                        fromRow: r,
                        fromCol: c,
                        toRow: dest.row,
                        toCol: dest.col,
                        promotion: dest.promotion || null
                    });
                }
            }
        }
    }

    if (allMoves.length === 0) return null;

    if (difficulty === 'easy') {
        const randomIndex = Math.floor(Math.random() * allMoves.length);
        return allMoves[randomIndex];
    }

    if (difficulty === 'medium') {
        // Prioritize captures and center control
        let bestMove = allMoves[0];
        let bestScore = -9999;

        for (const move of allMoves) {
            let score = Math.random() * 5; // slight randomness
            const target = board.getPiece(move.toRow, move.toCol);
            if (target) {
                const targetVal = PIECE_VALUES[target.toLowerCase()] || 10;
                score += targetVal * 10;
            }
            // Center preference
            if (move.toRow >= 2 && move.toRow <= 5 && move.toCol >= 2 && move.toCol <= 5) {
                score += 5;
            }

            if (score > bestScore) {
                bestScore = score;
                bestMove = move;
            }
        }
        return bestMove;
    }

    // Hard (1-ply lookahead with evaluation)
    let bestMove = allMoves[0];
    let bestScore = -99999;

    for (const move of allMoves) {
        const cloned = board.clone();
        cloned.setPiece(move.toRow, move.toCol, cloned.getPiece(move.fromRow, move.fromCol));
        cloned.setPiece(move.fromRow, move.fromCol, null);
        cloned.turn = aiColor === 'W' ? 'B' : 'W';

        const score = evaluateBoard(cloned, aiColor);
        if (score > bestScore) {
            bestScore = score;
            bestMove = move;
        }
    }

    return bestMove;
}

