/**
 * audio.js
 * Provides optional synthetic sound effects for moves, captures, checks, and game over 
 * using the Web Audio API without external audio files.
 */

export const SoundFX = {
  audioCtx: null,
  enabled: true,

  init() {
    // AudioContext will be initialized on first user interaction to comply with browser policies
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (AudioContext && !this.audioCtx) {
      this.audioCtx = new AudioContext();
    }
  },

  ensureContext() {
    if (!this.audioCtx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (AudioContext) {
        this.audioCtx = new AudioContext();
      }
    }
    if (this.audioCtx && this.audioCtx.state === 'suspended') {
      this.audioCtx.resume();
    }
  },

  toggleSound(forceState) {
    if (forceState !== undefined) {
      this.enabled = !!forceState;
    } else {
      this.enabled = !this.enabled;
    }
    return this.enabled;
  },

  playTone(freq, type, duration, gainValue = 0.1) {
    if (!this.enabled) return;
    try {
      this.ensureContext();
      if (!this.audioCtx) return;

      const osc = this.audioCtx.createOscillator();
      const gain = this.audioCtx.createGain();

      osc.type = type;
      osc.frequency.setValueAtTime(freq, this.audioCtx.currentTime);

      gain.gain.setValueAtTime(gainValue, this.audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, this.audioCtx.currentTime + duration);

      osc.connect(gain);
      gain.connect(this.audioCtx.destination);

      osc.start();
      osc.stop(this.audioCtx.currentTime + duration);
    } catch (e) {
      console.warn('Web Audio API playback prevented or failed:', e);
    }
  },

  playMove() {
    // Soft gentle wood-like thud for a standard move
    this.playTone(320, 'sine', 0.08, 0.08);
  },

  playCapture() {
    // Sharper, higher knock for capture
    this.playTone(440, 'triangle', 0.12, 0.12);
    setTimeout(() => this.playTone(220, 'sine', 0.1, 0.1), 40);
  },

  playCheck() {
    // Urgent double tone alert for check
    this.playTone(659.25, 'sawtooth', 0.15, 0.08); // E5
    setTimeout(() => {
      this.playTone(523.25, 'sawtooth', 0.2, 0.08);  // C5
    }, 120);
  },

  playWin() {
    // Triumphant arpeggio (C major: C4, E4, G4, C5)
    const notes = [261.63, 329.63, 392.00, 523.25];
    notes.forEach((note, index) => {
      setTimeout(() => {
        this.playTone(note, 'triangle', 0.25, 0.12);
      }, index * 120);
    });
  },

  playLoss() {
    // Sad descending tone
    const notes = [392.00, 329.63, 261.63, 196.00];
    notes.forEach((note, index) => {
      setTimeout(() => {
        this.playTone(note, 'sawtooth', 0.3, 0.1);
      }, index * 150);
    });
  }
};

