import { PIECES, COLORS, INITIAL_FEN } from './constants.js';

export class Board {
  constructor(fen = INITIAL_FEN) {
    this.grid = Array(8).fill(null).map(() => Array(8).fill(null));
    this.turn = COLORS.WHITE;
    this.castling = { K: true, Q: true, k: true, q: true };
    this.epSquare = null; // e.g. {row, col} or null
    this.halfmoveClock = 0;
    this.fullmoveNumber = 1;
    this.parseFEN(fen);
  }

  parseFEN(fen) {
    const parts = fen.trim().split(/\s+/);
    const placement = parts[0];
    const rows = placement.split('/');

    for (let r = 0; r < 8; r++) {
      let c = 0;
      const rowStr = rows[r];
      for (let i = 0; i < rowStr.length; i++) {
        const char = rowStr[i];
        if (!isNaN(char)) {
          const emptyCount = parseInt(char, 10);
          for (let e = 0; e < emptyCount; e++) {
            this.grid[r][c] = null;
            c++;
          }
        } else {
          const color = char === char.toUpperCase() ? COLORS.WHITE : COLORS.BLACK;
          const type = char.toLowerCase();
          this.grid[r][c] = { type, color, symbol: char };
          c++;
        }
      }
    }

    if (parts[1]) {
      this.turn = parts[1] === 'w' ? COLORS.WHITE : COLORS.BLACK;
    }

    if (parts[2]) {
      const castlingStr = parts[2];
      this.castling = {
        K: castlingStr.includes('K'),
        Q: castlingStr.includes('Q'),
        k: castlingStr.includes('k'),
        q: castlingStr.includes('q')
      };
    }

    if (parts[3] && parts[3] !== '-') {
      const col = parts[3].charCodeAt(0) - 97;
      const row = 8 - parseInt(parts[3][1], 10);
      this.epSquare = { row, col };
    } else {
      this.epSquare = null;
    }

    if (parts[4]) {
      this.halfmoveClock = parseInt(parts[4], 10) || 0;
    }

    if (parts[5]) {
      this.fullmoveNumber = parseInt(parts[5], 10) || 1;
    }
  }

  toFEN() {
    let fen = '';
    for (let r = 0; r < 8; r++) {
      let empty = 0;
      for (let c = 0; c < 8; c++) {
        const piece = this.grid[r][c];
        if (!piece) {
          empty++;
        } else {
          if (empty > 0) {
            fen += empty;
            empty = 0;
          }
          fen += piece.symbol;
        }
      }
      if (empty > 0) {
        fen += empty;
      }
      if (r < 7) fen += '/';
    }

    fen += ` ${this.turn === COLORS.WHITE ? 'w' : 'b'} `;

    let castlingStr = '';
    if (this.castling.K) castlingStr += 'K';
    if (this.castling.Q) castlingStr += 'Q';
    if (this.castling.k) castlingStr += 'k';
    if (this.castling.q) castlingStr += 'q';
    fen += castlingStr === '' ? '-' : castlingStr;

    if (this.epSquare) {
      const fileChar = String.fromCharCode(97 + this.epSquare.col);
      const rankChar = 8 - this.epSquare.row;
      fen += ` ${fileChar}${rankChar}`;
    } else {
      fen += ' -';
    }

    fen += ` ${this.halfmoveClock} ${this.fullmoveNumber}`;
    return fen;
  }

  getPiece(row, col) {
    if (!this.isValidSquare(row, col)) return null;
    return this.grid[row][col];
  }

  setPiece(row, col, piece) {
    if (this.isValidSquare(row, col)) {
      this.grid[row][col] = piece;
    }
  }

  isValidSquare(row, col) {
    return row >= 0 && row < 8 && col >= 0 && col < 8;
  }

  clone() {
    const cloned = new Board(this.toFEN());
    cloned.turn = this.turn;
    cloned.castling = { ...this.castling };
    cloned.epSquare = this.epSquare ? { ...this.epSquare } : null;
    cloned.halfmoveClock = this.halfmoveClock;
    cloned.fullmoveNumber = this.fullmoveNumber;
    return cloned;
  }

  findKing(color) {
    for (let r = 0; r < 8; r++) {
      for (let c = 0; c < 8; c++) {
        const p = this.grid[r][c];
        if (p && p.type === PIECES.KING && p.color === color) {
          return { row: r, col: c };
        }
      }
    }
    return null;
  }

  static squareToAlgebraic(row, col) {
    const file = String.fromCharCode(97 + col);
    const rank = 8 - row;
    return `${file}${rank}`;
  }

  static algebraicToSquare(alg) {
    if (!alg || alg.length < 2) return null;
    const col = alg.charCodeAt(0) - 97;
    const row = 8 - parseInt(alg[1], 10);
    return { row, col };
  }
}

