import { Board } from './board.js';
import { getLegalMoves, isInCheck, isCheckmate, isStalemate } from './rules.js';
import { getAIMove } from './ai.js';
import { SoundFX } from './audio.js';
import { COLORS } from './constants.js';

export class Game {
    constructor(renderer, inputHandler) {
        this.renderer = renderer;
        this.input = inputHandler;
        this.board = new Board();
        this.turn = COLORS.WHITE;
        this.history = [];
        this.capturedWhite = [];
        this.capturedBlack = [];
        this.selectedSquare = null;
        this.validMoves = [];
        this.lastMove = null;
        this.isGameOver = false;
        this.gameMode = 'pvp'; // 'pvp' or 'pve'
        this.aiDifficulty = 'medium';
        this.timeControl = 0; // 0 = unlimited, in seconds
        this.whiteTime = 0;
        this.blackTime = 0;
        this.timerInterval = null;

        this.initInputCallbacks();
        this.resetGame();
    }

    initInputCallbacks() {
        this.input.onSquareSelect = (row, col) => this.handleSquareSelect(row, col);
        this.input.onSquareMove = (fromRow, fromCol, toRow, toCol) => this.makeMove(fromRow, fromCol, toRow, toCol);
    }

    resetGame() {
        this.board = new Board();
        this.turn = COLORS.WHITE;
        this.history = [];
        this.capturedWhite = [];
        this.capturedBlack = [];
        this.selectedSquare = null;
        this.validMoves = [];
        this.lastMove = null;
        this.isGameOver = false;

        if (this.timeControl > 0) {
            this.whiteTime = this.timeControl;
            this.blackTime = this.timeControl;
            this.startTimer();
        } else {
            this.stopTimer();
        }

        this.updateUI();
    }

    setGameMode(mode, difficulty = 'medium') {
        this.gameMode = mode;
        this.aiDifficulty = difficulty;
        this.resetGame();
    }

    setTimeControl(seconds) {
        this.timeControl = seconds;
        this.resetGame();
    }

    startTimer() {
        this.stopTimer();
        if (this.timeControl <= 0) return;
        this.timerInterval = setInterval(() => {
            if (this.isGameOver) {
                this.stopTimer();
                return;
            }
            if (this.turn === COLORS.WHITE) {
                this.whiteTime--;
                if (this.whiteTime <= 0) {
                    this.whiteTime = 0;
                    this.endGameByTime(COLORS.BLACK);
                }
            } else {
                this.blackTime--;
                if (this.blackTime <= 0) {
                    this.blackTime = 0;
                    this.endGameByTime(COLORS.WHITE);
                }
            }
            this.updateTimersUI();
        }, 1000);
    }

    stopTimer() {
        if (this.timerInterval) {
            clearInterval(this.timerInterval);
            this.timerInterval = null;
        }
    }

    endGameByTime(winningColor) {
        this.isGameOver = true;
        this.stopTimer();
        const statusBanner = document.getElementById('status-banner');
        if (statusBanner) {
            statusBanner.textContent = `${winningColor === COLORS.WHITE ? 'White' : 'Black'} wins on time!`;
            statusBanner.classList.remove('hidden');
        }
    }

    handleSquareSelect(row, col) {
        if (this.isGameOver) return;
        if (this.gameMode === 'pve' && this.turn === COLORS.BLACK) return; // AI turn

        const piece = this.board.getPiece(row, col);

        if (this.selectedSquare) {
            const [sRow, sCol] = this.selectedSquare;
            const moveMatch = this.validMoves.find(m => m.row === row && m.col === col);

            if (moveMatch) {
                this.makeMove(sRow, sCol, row, col, moveMatch.promotion);
                return;
            }
        }

        if (piece && piece.color === this.turn) {
            this.selectedSquare = [row, col];
            this.validMoves = getLegalMoves(this.board, row, col);
            SoundFX.playTone(440, 0.05); // SoundFX has playTone, playMove, playCapture, playCheck, playWin, playLoss etc.
        } else {
            this.selectedSquare = null;
            this.validMoves = [];
        }

        this.updateUI();
    }

    makeMove(fromRow, fromCol, toRow, toCol, promotionPiece = 'q') {
        const targetPiece = this.board.getPiece(toRow, toCol);
        const movingPiece = this.board.getPiece(fromRow, fromCol);

        if (!movingPiece) return false;

        // Check if move is legal
        const legalMoves = getLegalMoves(this.board, fromRow, fromCol);
        const match = legalMoves.find(m => m.row === toRow && m.col === toCol);
        if (!match) return false;

        // Handle promotion if triggered and not specified
        if (movingPiece.type === 'p' && (toRow === 0 || toRow === 7) && !match.promotion) {
            // If UI needs promotion choice, we could trigger modal. For simplicity, default to Q or prompt.
            // Assuming match.promotion handles it or we pass promotionPiece.
        }

        const boardSnapshot = this.board.clone();

        // Execute move
        this.board.setPiece(toRow, toCol, movingPiece);
        this.board.setPiece(fromRow, fromCol, null);

        // Promotion override
        if (movingPiece.type === 'p' && (toRow === 0 || toRow === 7)) {
            this.board.setPiece(toRow, toCol, { type: promotionPiece, color: movingPiece.color });
        }

        // Captured pieces tracking
        if (targetPiece) {
            if (targetPiece.color === COLORS.WHITE) {
                this.capturedWhite.push(targetPiece.type);
            } else {
                this.capturedBlack.push(targetPiece.type);
            }
            SoundFX.playCapture();
        } else {
            SoundFX.playMove();
        }

        // Save history
        const fromAlg = this.board.squareToAlgebraic(fromRow, fromCol);
        const toAlg = this.board.squareToAlgebraic(toRow, toCol);
        this.history.push({
            boardSnapshot,
            from: [fromRow, fromCol],
            to: [toRow, toCol],
            movingPiece,
            targetPiece,
            notation: `${fromAlg}-${toAlg}`
        });

        this.lastMove = { from: [fromRow, fromCol], to: [toRow, toCol] };
        this.selectedSquare = null;
        this.validMoves = [];

        // Switch turn
        this.turn = this.turn === COLORS.WHITE ? COLORS.BLACK : COLORS.WHITE;

        this.checkGameStatus();
        this.updateUI();

        // Check AI move
        if (!this.isGameOver && this.gameMode === 'pve' && this.turn === COLORS.BLACK) {
            setTimeout(() => this.triggerAIMove(), 300);
        }

        return true;
    }

    triggerAIMove() {
        if (this.isGameOver) return;
        const aiMove = getAIMove(this.board, this.aiDifficulty);
        if (aiMove) {
            this.makeMove(aiMove.fromRow, aiMove.fromCol, aiMove.toRow, aiMove.toCol, aiMove.promotion || 'q');
        }
    }

    undoMove() {
        if (this.history.length === 0 || this.isGameOver) return;

        // In PvE, undo two moves (player and AI)
        const steps = (this.gameMode === 'pve' && this.history.length >= 2) ? 2 : 1;

        for (let i = 0; i < steps; i++) {
            const last = this.history.pop();
            if (!last) break;
            this.board = last.boardSnapshot;
            this.turn = last.movingPiece.color;
            if (last.targetPiece) {
                if (last.targetPiece.color === COLORS.WHITE) this.capturedWhite.pop();
                else this.capturedBlack.pop();
            }
        }

        this.selectedSquare = null;
        this.validMoves = [];
        this.lastMove = this.history.length > 0 ? { from: this.history[this.history.length - 1].from, to: this.history[this.history.length - 1].to } : null;
        this.isGameOver = false;

        const statusBanner = document.getElementById('status-banner');
        if (statusBanner) statusBanner.classList.add('hidden');

        SoundFX.playMove();
        this.updateUI();
    }

    checkGameStatus() {
        const inCheck = isInCheck(this.board, this.turn);
        const checkmate = isCheckmate(this.board, this.turn);
        const stalemate = isStalemate(this.board, this.turn);

        const statusBanner = document.getElementById('status-banner');

        if (checkmate) {
            this.isGameOver = true;
            this.stopTimer();
            SoundFX.playWin();
            if (statusBanner) {
                const winner = this.turn === COLORS.WHITE ? 'Black' : 'White';
                statusBanner.textContent = `Checkmate! ${winner} wins.`;
                statusBanner.classList.remove('hidden');
            }
        } else if (stalemate) {
            this.isGameOver = true;
            this.stopTimer();
            SoundFX.playLoss();
            if (statusBanner) {
                statusBanner.textContent = `Stalemate! Draw game.`;
                statusBanner.classList.remove('hidden');
            }
        } else if (inCheck) {
            SoundFX.playCheck();
            if (statusBanner) {
                statusBanner.textContent = `${this.turn === COLORS.WHITE ? 'White' : 'Black'} is in check!`;
                statusBanner.classList.remove('hidden');
            }
        } else {
            if (statusBanner) {
                statusBanner.classList.add('hidden');
            }
        }
    }

    updateUI() {
        this.renderer.render(this.board, this.selectedSquare, this.validMoves, this.lastMove);
        this.updateHistoryUI();
        this.updateCapturedUI();
        this.updateTimersUI();
    }

    updateHistoryUI() {
        const historyList = document.getElementById('move-history-list');
        if (!historyList) return;
        historyList.innerHTML = '';

        for (let i = 0; i < this.history.length; i += 2) {
            const item = document.createElement('div');
            const whiteMove = this.history[i]?.notation || '';
            const blackMove = this.history[i + 1]?.notation || '';
            item.textContent = `${Math.floor(i / 2) + 1}. ${whiteMove}  ${blackMove}`;
            historyList.appendChild(item);
        }
        historyList.scrollTop = historyList.scrollHeight;
    }

    updateCapturedUI() {
        const capWhiteEl = document.getElementById('captured-white');
        const capBlackEl = document.getElementById('captured-black');

        if (capWhiteEl) capWhiteEl.textContent = this.capturedWhite.join(' ');
        if (capBlackEl) capBlackEl.textContent = this.capturedBlack.join(' ');
    }

    updateTimersUI() {
        const timerWhite = document.getElementById('timer-white');
        const timerBlack = document.getElementById('timer-black');

        if (timerWhite) {
            timerWhite.textContent = this.formatTime(this.whiteTime);
            timerWhite.classList.toggle('hidden', this.timeControl <= 0);
        }
        if (timerBlack) {
            timerBlack.textContent = this.formatTime(this.blackTime);
            timerBlack.classList.toggle('hidden', this.timeControl <= 0);
        }
    }

    formatTime(seconds) {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
    }
}

