/**
 * input.js
 * Handles touch and mouse interactions for tablet devices, supporting
 * tap-to-select, tap-to-move, and drag-and-drop piece mechanics.
 */

export class InputHandler {
    constructor(chessboardElement, onSquareSelect, onSquareMove, onDragStart, onDragEnd) {
        this.boardEl = chessboardElement;
        this.onSquareSelect = onSquareSelect; // callback(row, col)
        this.onSquareMove = onSquareMove;     // callback(fromRow, fromCol, toRow, toCol)
        this.onDragStart = onDragStart;       // callback(row, col)
        this.onDragEnd = onDragEnd;           // callback()

        this.selectedSquare = null; // {row, col}
        this.draggedPieceEl = null;
        this.dragStartSquare = null;
        this.pointerDownPos = { x: 0, y: 0 };
        this.isDragging = false;

        this.bindEvents();
    }

    bindEvents() {
        if (!this.boardEl) return;

        // Mouse events
        this.boardEl.addEventListener('mousedown', (e) => this.handlePointerDown(e));
        window.addEventListener('mousemove', (e) => this.handlePointerMove(e));
        window.addEventListener('mouseup', (e) => this.handlePointerUp(e));

        // Touch events
        this.boardEl.addEventListener('touchstart', (e) => this.handlePointerDown(e), { passive: false });
        window.addEventListener('touchmove', (e) => this.handlePointerMove(e), { passive: false });
        window.addEventListener('touchend', (e) => this.handlePointerUp(e));
        window.addEventListener('touchcancel', (e) => this.handlePointerUp(e));
    }

    getEventCoordinates(e) {
        if (e.touches && e.touches.length > 0) {
            return { x: e.touches[0].clientX, y: e.touches[0].clientY };
        }
        if (e.changedTouches && e.changedTouches.length > 0) {
            return { x: e.changedTouches[0].clientX, y: e.changedTouches[0].clientY };
        }
        return { x: e.clientX, y: e.clientY };
    }

    getSquareFromPoint(x, y) {
        const target = document.elementFromPoint(x, y);
        if (!target) return null;
        const squareEl = target.closest('.square');
        if (!squareEl || !this.boardEl.contains(squareEl)) return null;

        const row = parseInt(squareEl.dataset.row, 10);
        const col = parseInt(squareEl.dataset.col, 10);
        if (isNaN(row) || isNaN(col)) return null;

        return { row, col, element: squareEl };
    }

    handlePointerDown(e) {
        const coords = this.getEventCoordinates(e);
        this.pointerDownPos = coords;
        this.isDragging = false;

        const sq = this.getSquareFromPoint(coords.x, coords.y);
        if (!sq) return;

        const pieceEl = sq.element.querySelector('.piece');
        if (pieceEl) {
            this.dragStartSquare = { row: sq.row, col: sq.col };
            // Do not prevent default immediately so clicks still register nicely, 
            // but for touch we prepare drag
        }
    }

    handlePointerMove(e) {
        const coords = this.getEventCoordinates(e);
        const dx = coords.x - this.pointerDownPos.x;
        const dy = coords.y - this.pointerDownPos.y;

        // If moved more than 8 pixels, trigger drag mode
        if (!this.isDragging && this.dragStartSquare && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) {
            const sqEl = this.boardEl.querySelector(`.square[data-row="${this.dragStartSquare.row}"][data-col="${this.dragStartSquare.col}"]`);
            if (sqEl) {
                const pieceEl = sqEl.querySelector('.piece');
                if (pieceEl) {
                    this.isDragging = true;
                    if (this.onDragStart) {
                        this.onDragStart(this.dragStartSquare.row, this.dragStartSquare.col);
                    }

                    // Create floating clone for smooth drag
                    this.draggedPieceEl = pieceEl.cloneNode(true);
                    this.draggedPieceEl.classList.add('dragging-piece');
                    this.draggedPieceEl.style.position = 'fixed';
                    this.draggedPieceEl.style.zIndex = '1000';
                    this.draggedPieceEl.style.pointerEvents = 'none';
                    this.updateDraggedPosition(coords.x, coords.y);
                    document.body.appendChild(this.draggedPieceEl);

                    // Dim original piece
                    pieceEl.style.opacity = '0.4';
                }
            }
        }

        if (this.isDragging && this.draggedPieceEl) {
            if (e.cancelable) e.preventDefault();
            this.updateDraggedPosition(coords.x, coords.y);
        }
    }

    updateDraggedPosition(x, y) {
        if (!this.draggedPieceEl) return;
        const width = this.draggedPieceEl.offsetWidth || 50;
        const height = this.draggedPieceEl.offsetHeight || 50;
        this.draggedPieceEl.style.left = `${x - width / 2}px`;
        this.draggedPieceEl.style.top = `${y - height / 2}px`;
    }

    handlePointerUp(e) {
        const coords = this.getEventCoordinates(e);
        const sq = this.getSquareFromPoint(coords.x, coords.y);

        if (this.isDragging) {
            if (e.cancelable) e.preventDefault();
            this.isDragging = false;

            if (this.draggedPieceEl) {
                this.draggedPieceEl.remove();
                this.draggedPieceEl = null;
            }

            // Restore opacity of original piece
            if (this.dragStartSquare) {
                const origSqEl = this.boardEl.querySelector(`.square[data-row="${this.dragStartSquare.row}"][data-col="${this.dragStartSquare.col}"]`);
                if (origSqEl) {
                    const p = origSqEl.querySelector('.piece');
                    if (p) p.style.opacity = '1';
                }
            }

            if (this.onDragEnd) {
                this.onDragEnd();
            }

            if (sq && this.dragStartSquare) {
                if (this.dragStartSquare.row !== sq.row || this.dragStartSquare.col !== sq.col) {
                    if (this.onSquareMove) {
                        this.onSquareMove(this.dragStartSquare.row, this.dragStartSquare.col, sq.row, sq.col);
                    }
                } else {
                    // Dropped on same square -> treat as tap select
                    if (this.onSquareSelect) {
                        this.onSquareSelect(sq.row, sq.col);
                    }
                }
            }
            this.dragStartSquare = null;
        } else {
            // Tap / Click interaction
            if (sq) {
                if (this.onSquareSelect) {
                    this.onSquareSelect(sq.row, sq.col);
                }
            }
            this.dragStartSquare = null;
        }
    }
}

