import { Game } from './game.js';
import { BoardRenderer } from './renderer.js';
import { InputHandler } from './input.js';
import { UIManager } from './ui.js';
import { SoundFX } from './audio.js';

document.addEventListener('DOMContentLoaded', () => {
    const chessboardElement = document.getElementById('chessboard');
    if (!chessboardElement) {
        console.error('Chessboard element not found in DOM.');
        return;
    }

    const renderer = new BoardRenderer(chessboardElement);

    // Create the dummy input handler. Game constructor wires up input callbacks.
    const inputHandler = new InputHandler(
        chessboardElement,
        (r, c) => game.handleSquareSelect(r, c),
        (fr, fc, tr, tc) => game.makeMove(fr, fc, tr, tc),
        (r, c) => {},
        () => {}
    );

    const game = new Game(renderer, inputHandler);
    const uiManager = new UIManager(game);

    // Make game and uiManager globally available or pass references if needed
    window.chessGame = game;
    window.uiManager = uiManager;

    // Sound toggle button wiring
    const btnSound = document.getElementById('btn-sound');
    if (btnSound) {
        btnSound.addEventListener('click', () => {
            const enabled = SoundFX.toggleSound();
            btnSound.classList.toggle('active', enabled);
            btnSound.textContent = enabled ? '🔊 Sound: On' : '🔇 Sound: Off';
        });
    }

    console.log('Tablet Chess initialized successfully.');
});

