import { UNICODE_PIECES, COLORS } from './constants.js';

export class BoardRenderer {
    constructor(chessboardElement) {
        this.chessboard = chessboardElement;
        this.squares = new Map(); // "row,col" -> DOM element
        this.renderGrid();
    }

    renderGrid() {
        if (!this.chessboard) return;
        this.chessboard.innerHTML = '';
        this.squares.clear();

        for (let row = 0; row < 8; row++) {
            for (let col = 0; col < 8; col++) {
                const square = document.createElement('div');
                square.className = `square ${(row + col) % 2 === 0 ? 'light' : 'dark'}`;
                square.dataset.row = row;
                square.dataset.col = col;

                const fileLetter = String.fromCharCode(97 + col);
                const rankNumber = 8 - row;
                square.dataset.square = `${fileLetter}${rankNumber}`;

                this.chessboard.appendChild(square);
                this.squares.set(`${row},${col}`, square);
            }
        }
    }

    render(board, selectedSquare = null, validMoves = [], lastMove = null) {
        if (!this.chessboard) return;

        for (let row = 0; row < 8; row++) {
            for (let col = 0; col < 8; col++) {
                const key = `${row},${col}`;
                const sqEl = this.squares.get(key);
                if (!sqEl) continue;

                // Reset classes
                const isLight = (row + col) % 2 === 0;
                sqEl.className = `square ${isLight ? 'light' : 'dark'}`;

                // Last move highlight
                if (lastMove && ((lastMove.fromRow === row && lastMove.fromCol === col) || (lastMove.toRow === row && lastMove.toCol === col))) {
                    sqEl.classList.add('last-move');
                }

                // Selected highlight
                if (selectedSquare && selectedSquare.row === row && selectedSquare.col === col) {
                    sqEl.classList.add('selected');
                }

                // Valid move highlight
                const isValidDest = validMoves.some(m => m.row === row && m.col === col);
                if (isValidDest) {
                    const piece = board.getPiece(row, col);
                    if (piece) {
                        sqEl.classList.add('valid-capture');
                    } else {
                        sqEl.classList.add('valid-move');
                    }
                }

                // King in check highlight
                const piece = board.getPiece(row, col);
                if (piece && piece.type === 'k') {
                    const kingColor = piece.color;
                    // We can check if this king's square is in check if needed, but rules engine handles status
                }

                // Render piece
                sqEl.innerHTML = '';
                if (piece) {
                    const pieceEl = document.createElement('div');
                    pieceEl.className = `piece ${piece.color === COLORS.WHITE ? 'white' : 'black'}`;
                    pieceEl.dataset.type = piece.type;
                    pieceEl.dataset.color = piece.color;
                    pieceEl.textContent = UNICODE_PIECES[piece.color][piece.type] || '';
                    sqEl.appendChild(pieceEl);
                }
            }
        }
    }
}

