}

#sidebar-panel {
  grid-column: 2;
  grid-row: 1 / span 3;
  width: 280px;
  display: flex;
  flex-direction: column;
  background-color: rgba(15, 23, 42, 0.4);
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  overflow: hidden;
}

.panel {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.panel h3 {
  padding: 0.75rem 1rem;
  background-color: var(--panel-border);
  font-size: 0.95rem;
  font-weight: 600;
  border-bottom: 1px solid var(--panel-border);
}

.history-list {
  flex: 1;
  overflow-y: auto;
  padding: 0.5rem;
  font-family: monospace;
  font-size: 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.history-row {
  display: grid;
  grid-template-columns: 40px 1fr 1fr;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
}

.history-row:nth-child(even) {
  background-color: rgba(255, 255, 255, 0.03);
}

.history-num {
  color: var(--text-muted);
}

.modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  opacity: 1;
  transition: opacity 0.2s;
}

.modal.hidden {
  opacity: 0;
  pointer-events: none;
}

.modal-content {
  background-color: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  padding: 1.5rem;
  width: 90%;
  max-width: 400px;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5);
}

.modal-content h2 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  text-align: center;
}

.promotion-choices {
  display: flex;
  justify-content: space-around;
  font-size: 3rem;
  margin: 1.5rem 0;
  cursor: pointer;
}

.promotion-choices span {
  padding: 0.5rem;
  border-radius: 8px;
  background-color: var(--panel-border);
  transition: background-color 0.2s, transform 0.1s;
}

.promotion-choices span:hover {
  background-color: var(--accent-color);
  transform: scale(1.1);
}

.setting-group {
  margin-bottom: 1rem;
}

.setting-group label {
  display: block;
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.setting-group select {
  width: 100%;
  padding: 0.75rem;
  background-color: var(--bg-color);
  color: var(--text-color);
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  font-size: 1rem;
  outline: none;
}

@media (max-width: 850px) {
  #app-container {
    height: auto;
    max-height: none;
    padding: 0.5rem;
  }

  #game-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto auto;
  }

  #sidebar-panel {
    grid-column: 1;
    grid-row: 4;
    width: 100%;
    height: 180px;
    margin-top: 0.5rem;
  }

  :root {
    --board-size: min(85vw, 60vh, 450px);
  }
}

