import { UNICODE_PIECES } from './constants.js';

export class UIManager {
    constructor(game) {
        this.game = game;
        this.cacheElements();
        this.bindEvents();
    }

    cacheElements() {
        this.btnNewGame = document.getElementById('btn-new-game');
        this.btnSettings = document.getElementById('btn-settings');
        this.btnUndo = document.getElementById('btn-undo');
        this.btnSound = document.getElementById('btn-sound');

        this.statusBanner = document.getElementById('status-banner');
        this.moveHistoryList = document.getElementById('move-history-list');

        this.timerWhite = document.getElementById('timer-white');
        this.timerBlack = document.getElementById('timer-black');
        this.capturedWhite = document.getElementById('captured-white');
        this.capturedBlack = document.getElementById('captured-black');

        this.promotionModal = document.getElementById('promotion-modal');
        this.promotionChoices = document.getElementById('promotion-choices');

        this.settingsModal = document.getElementById('settings-modal');
        this.selectMode = document.getElementById('select-mode');
        this.selectTime = document.getElementById('select-time');
        this.btnCloseSettings = document.getElementById('btn-close-settings');

        this.playerWhitePanel = document.getElementById('player-white-panel');
        this.playerBlackPanel = document.getElementById('player-black-panel');
    }

    bindEvents() {
        if (this.btnNewGame) {
            this.btnNewGame.addEventListener('click', () => {
                this.game.resetGame();
            });
        }

        if (this.btnUndo) {
            this.btnUndo.addEventListener('click', () => {
                this.game.undoMove();
            });
        }

        if (this.btnSettings) {
            this.btnSettings.addEventListener('click', () => {
                this.openSettingsModal();
            });
        }

        if (this.btnCloseSettings) {
            this.btnCloseSettings.addEventListener('click', () => {
                this.closeSettingsModal();
            });
        }

        if (this.selectMode) {
            this.selectMode.addEventListener('change', (e) => {
                const parts = e.target.value.split('-');
                const mode = parts[0];
                const diff = parts[1] || 'medium';
                this.game.setGameMode(mode, diff);
            });
        }

        if (this.selectTime) {
            this.selectTime.addEventListener('change', (e) => {
                const seconds = parseInt(e.target.value, 10);
                this.game.setTimeControl(seconds);
            });
        }

        if (this.btnSound) {
            this.btnSound.addEventListener('click', () => {
                this.btnSound.classList.toggle('active');
                const muted = !this.btnSound.classList.contains('active');
                if (this.game.renderer && this.game.renderer.soundFX) {
                    this.game.renderer.soundFX.muted = muted;
                }
            });
        }

        // Close modals on backdrop click
        window.addEventListener('click', (e) => {
            if (e.target === this.settingsModal) {
                this.closeSettingsModal();
            }
        });
    }

    updateStatus(message, type = '') {
        if (!this.statusBanner) return;
        this.statusBanner.textContent = message;
        this.statusBanner.className = 'status-banner ' + type;
    }

    updateTimers(whiteTime, blackTime, activeColor) {
        if (this.timerWhite) {
            this.timerWhite.textContent = this.formatTime(whiteTime);
            this.timerWhite.classList.toggle('active', activeColor === 'w');
        }
        if (this.timerBlack) {
            this.timerBlack.textContent = this.formatTime(blackTime);
            this.timerBlack.classList.toggle('active', activeColor === 'b');
        }
    }

    formatTime(seconds) {
        if (seconds === null || seconds === undefined) return '--:--';
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
    }

    updateHistory(history) {
        if (!this.moveHistoryList) return;
        this.moveHistoryList.innerHTML = '';

        for (let i = 0; i < history.length; i += 2) {
            const moveNum = Math.floor(i / 2) + 1;
            const whiteMove = history[i] ? history[i].san : '';
            const blackMove = history[i + 1] ? history[i + 1].san : '';

            const row = document.createElement('div');
            row.className = 'history-row';

            const numSpan = document.createElement('span');
            numSpan.className = 'history-num';
            numSpan.textContent = `${moveNum}.`;

            const whiteSpan = document.createElement('span');
            whiteSpan.className = 'history-move';
            whiteSpan.textContent = whiteMove;

            const blackSpan = document.createElement('span');
            blackSpan.className = 'history-move';
            blackSpan.textContent = blackMove;

            row.appendChild(numSpan);
            row.appendChild(whiteSpan);
            row.appendChild(blackSpan);
            this.moveHistoryList.appendChild(row);
        }

        this.moveHistoryList.scrollTop = this.moveHistoryList.scrollHeight;
    }

    updateCaptured(capturedWhitePieces, capturedBlackPieces) {
        if (this.capturedWhite) {
            this.capturedWhite.innerHTML = capturedWhitePieces
                .map(p => UNICODE_PIECES[p.color][p.type])
                .join(' ');
        }
        if (this.capturedBlack) {
            this.capturedBlack.innerHTML = capturedBlackPieces
                .map(p => UNICODE_PIECES[p.color][p.type])
                .join(' ');
        }
    }

    showPromotionModal(color, onSelect) {
        if (!this.promotionModal || !this.promotionChoices) return;
        this.promotionChoices.innerHTML = '';
        const pieces = ['q', 'r', 'b', 'n'];

        pieces.forEach(type => {
            const btn = document.createElement('button');
            btn.className = 'btn';
            btn.innerHTML = UNICODE_PIECES[color][type];
            btn.style.fontSize = '2rem';
            btn.addEventListener('click', () => {
                this.hidePromotionModal();
                onSelect(type);
            });
            this.promotionChoices.appendChild(btn);
        });

        this.promotionModal.classList.remove('hidden');
    }

    hidePromotionModal() {
        if (this.promotionModal) {
            this.promotionModal.classList.add('hidden');
        }
    }

    openSettingsModal() {
        if (this.settingsModal) {
            this.settingsModal.classList.remove('hidden');
        }
    }

    closeSettingsModal() {
        if (this.settingsModal) {
            this.settingsModal.classList.add('hidden');
        }
    }
}
